CREATE DATABASE IF NOT EXISTS gamematch CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gamematch;

SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS ratings;
DROP TABLE IF EXISTS wishlists;
DROP TABLE IF EXISTS store_offers;
DROP TABLE IF EXISTS games;
DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE users (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(100) NOT NULL,
 email VARCHAR(190) NOT NULL UNIQUE,
 password VARCHAR(255) NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE games (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 title VARCHAR(150) NOT NULL,
 slug VARCHAR(170) NOT NULL UNIQUE,
 developer VARCHAR(150) DEFAULT NULL,
 publisher VARCHAR(150) DEFAULT NULL,
 release_date DATE DEFAULT NULL,
 platforms VARCHAR(255) NOT NULL,
 genres VARCHAR(255) NOT NULL,
 game_mode VARCHAR(100) NOT NULL,
 age_rating VARCHAR(20) DEFAULT 'T',
 price DECIMAL(10,2) NOT NULL DEFAULT 0,
 description TEXT NOT NULL,
 cover_image VARCHAR(500) NOT NULL,
 trailer_url VARCHAR(500) DEFAULT NULL,
 steam_app_id INT DEFAULT NULL,
 source VARCHAR(40) NOT NULL DEFAULT 'manual',
 external_id VARCHAR(190) DEFAULT NULL,
 last_synced_at TIMESTAMP NULL DEFAULT NULL,
 store_rating DECIMAL(4,1) DEFAULT NULL,
 rating_count BIGINT DEFAULT 0,
 rating_source VARCHAR(50) DEFAULT NULL,
 featured TINYINT(1) NOT NULL DEFAULT 0,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uq_game_source_external (source, external_id),
 INDEX idx_game_source (source),
 INDEX idx_game_synced (last_synced_at)
) ENGINE=InnoDB;

CREATE TABLE catalog_sync_state (
 source VARCHAR(40) PRIMARY KEY,
 cursor_value VARCHAR(190) DEFAULT NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'idle',
 last_run_at TIMESTAMP NULL DEFAULT NULL,
 last_success_at TIMESTAMP NULL DEFAULT NULL,
 last_error TEXT DEFAULT NULL
) ENGINE=InnoDB;

CREATE TABLE external_catalog (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 source VARCHAR(40) NOT NULL,
 external_id VARCHAR(190) NOT NULL,
 name VARCHAR(255) NOT NULL,
 is_game TINYINT(1) DEFAULT NULL,
 enriched TINYINT(1) NOT NULL DEFAULT 0,
 last_seen_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 enriched_at TIMESTAMP NULL DEFAULT NULL,
 UNIQUE KEY uq_external_catalog (source, external_id),
 INDEX idx_external_enriched (source, enriched, id)
) ENGINE=InnoDB;

CREATE TABLE store_offers (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 game_id INT UNSIGNED NOT NULL,
 store_name VARCHAR(50) NOT NULL,
 platform VARCHAR(40) NOT NULL,
 price DECIMAL(10,2) NOT NULL DEFAULT 0,
 original_price DECIMAL(10,2) DEFAULT NULL,
 currency VARCHAR(10) NOT NULL DEFAULT 'INR',
 url VARCHAR(1000) NOT NULL,
 is_official TINYINT(1) NOT NULL DEFAULT 1,
 source VARCHAR(40) NOT NULL DEFAULT 'catalog',
 external_id VARCHAR(190) DEFAULT NULL,
 is_available TINYINT(1) NOT NULL DEFAULT 1,
 last_checked_at TIMESTAMP NULL DEFAULT NULL,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_offer_game FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE,
 INDEX idx_offer_game_price(game_id, price),
 INDEX idx_offer_store(store_name),
 UNIQUE KEY uq_offer_source_external (game_id, store_name, external_id)
) ENGINE=InnoDB;

CREATE TABLE wishlists (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 game_id INT UNSIGNED NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY unique_wishlist (user_id, game_id),
 FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE ratings (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 game_id INT UNSIGNED NOT NULL,
 rating TINYINT UNSIGNED NOT NULL,
 review VARCHAR(1000) DEFAULT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 source VARCHAR(40) NOT NULL DEFAULT 'catalog',
 external_id VARCHAR(190) DEFAULT NULL,
 is_available TINYINT(1) NOT NULL DEFAULT 1,
 last_checked_at TIMESTAMP NULL DEFAULT NULL,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY unique_rating (user_id, game_id),
 FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE
) ENGINE=InnoDB;




